const ee = require('@google/earthengine'); 
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const bearIslandLat = 74.5;
    const bearIslandLon = 19.0;
    const kmToDegreesLat = 1 / 111.12; // Approx 1 degree latitude = 111.12 km

    // Location 1: 100 km south of Bear Island
    const lat1 = bearIslandLat - (100 * kmToDegreesLat);
    const point1 = ee.Geometry.Point(bearIslandLon, lat1);
    const region1 = point1.buffer(5000); // 5 km radius around the point

    // Location 2: 250 km south of Bear Island
    const lat2 = bearIslandLat - (250 * kmToDegreesLat);
    const point2 = ee.Geometry.Point(bearIslandLon, lat2);
    const region2 = point2.buffer(5000); // 5 km radius around the point

    // Since the request is for a future date (August 5, 2025),
    // we use a recent past period around the same date for representative conditions.
    const startDate = '2023-08-01';
    const endDate = '2023-08-10'; // 10-day window around Aug 5, 2023

    // 2. Data Acquisition & Check
    let s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(startDate, endDate)
      .filterBounds(region1.union(region2));

    // Cloud masking function for Sentinel-2 SR
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000); // Scale to 0-1 reflectance
    }

    s2Collection = s2Collection.map(maskS2clouds)
      .select(['B2', 'B3', 'B4']); // Select Blue, Green, Red bands

    const collection1 = s2Collection.filterBounds(region1);
    const collection2 = s2Collection.filterBounds(region2);

    const size1 = await collection1.size().getInfo();
    const size2 = await collection2.size().getInfo();

    if (size1 === 0 && size2 === 0) {
      console.log("Empty Collection (no images for both locations)");
      console.log("C1");
      return;
    } else if (size1 === 0) {
      console.log("Empty Collection (no images for 100km south location)");
      console.log("C1");
      return;
    } else if (size2 === 0) {
      console.log("Empty Collection (no images for 250km south location)");
      console.log("C1");
      return;
    }

    // Get the median image for each region
    const image1 = collection1.median();
    const image2 = collection2.median();

    // 3. Processing & Calculation
    // We'll use the Blue band (B2) reflectance as an indicator for 'milky turquoise-blue'.
    // Higher B2 reflectance suggests brighter blue, which can indicate suspended particles.
    const scale = 1000; // Use a reasonable scale to avoid memory issues for regional mean
    const maxPixels = 1e9;

    const reduceParams = {
      reducer: ee.Reducer.mean(),
      scale: scale,
      maxPixels: maxPixels,
      bestEffort: true
    };

    const meanB2_1_obj = await image1.select('B2').reduceRegion({geometry: region1, ...reduceParams}).getInfo();
    const meanB2_2_obj = await image2.select('B2').reduceRegion({geometry: region2, ...reduceParams}).getInfo();

    const meanB2_1 = meanB2_1_obj ? meanB2_1_obj.B2 : null;
    const meanB2_2 = meanB2_2_obj ? meanB2_2_obj.B2 : null;

    // Check for C2 (No Valid Pixels)
    if (meanB2_1 === null || isNaN(meanB2_1)) {
        console.log(`No valid pixels for 100 km south (mean B2: ${meanB2_1}).`);
        console.log("C2");
        return;
    }
    if (meanB2_2 === null || isNaN(meanB2_2)) {
        console.log(`No valid pixels for 250 km south (mean B2: ${meanB2_2}).`);
        console.log("C2");
        return;
    }

    // 5. Validation & Final Answer
    console.log(`Mean B2 (100km south): ${meanB2_1.toFixed(4)}`);
    console.log(`Mean B2 (250km south): ${meanB2_2.toFixed(4)}`);

    if (meanB2_1 === null || meanB2_2 === null || isNaN(meanB2_1) || isNaN(meanB2_2)) {
      console.log("Calculation Failure (NaN or null result).");
      console.log("C3");
    } else if (meanB2_1 > meanB2_2) {
      console.log("A"); // More milky turquoise-blue color (higher B2 reflectance)
    } else {
      console.log("B"); // Not more milky turquoise-blue color
    }

  } catch (e) {
    console.error("An error occurred: ", e);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
